/**
 * Generates assets/brand-tokens.css from the repository's brand/brand.json.
 *
 * The repo rule (CLAUDE.md) is that brand.json is the one source of brand
 * values and must be imported, never copied. A HyperFrames composition renders
 * as static HTML and cannot fetch JSON at render time without breaking the
 * determinism contract, so this script does the import at build time and writes
 * CSS custom properties. The generated file is output, not a second source of
 * truth: re-run this whenever brand.json changes.
 *
 *   node scripts/build-brand-css.mjs
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const brandPath = resolve(here, "../../../brand/brand.json");
const outPath = resolve(here, "../assets/brand-tokens.css");

const brand = JSON.parse(readFileSync(brandPath, "utf8"));

/** camelCase token name -> kebab-case CSS custom property. */
const kebab = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase();

const colorLines = Object.entries(brand.color.palette).map(
  ([token, def]) => `  --ls-${kebab(token)}: ${def.hex}; /* ${def.name} */`,
);

const fontStack = brand.typography.fallbackStack
  .map((f) => (f.includes(" ") ? `"${f}"` : f))
  .join(", ");

const out = `/* GENERATED by scripts/build-brand-css.mjs from brand/brand.json — do not edit.
   brand version ${brand.brandVersion}, schema ${brand.schemaVersion}
   Source of truth: ${brand.sourceOfTruth.document}
   Colors are page ${brand.color._source.replace(/^page /, "")}; type is ${brand.typography._source}.
   Values the guidelines do not specify (gradient stops, corner radius, type
   sizes, motion timing) are deliberately absent here — see brand.json's
   notSpecifiedInSource. Do not invent them into this file. */
:root {
${colorLines.join("\n")}

  --ls-font: ${fontStack};
  --ls-weight-title: ${brand.typography.hierarchy.find((h) => h.level === "categoryTitle").weight};
  --ls-weight-item: ${brand.typography.hierarchy.find((h) => h.level === "menuItem").weight};
  --ls-weight-body: ${brand.typography.hierarchy.find((h) => h.level === "description").weight};
}
`;

mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, out, "utf8");
console.log(`wrote ${outPath}`);
console.log(out);
